primaryQuery:
run: order_items -> {
  aggregate:
    returned_items is count() { where: status = 'Returned' }
    delivered_items is count() { where: delivered_at is not null }
} -> {
  select:
    returned_items
    delivered_items
    return_share_of_delivered is round(returned_items / delivered_items, 6)
}

verifyQuery:
run: order_items -> {
  group_by: status
  aggregate: n is count(), d is count() { where: delivered_at is not null }
} -> {
  aggregate:
    returned_items is n.sum() { where: status = 'Returned' }
    delivered_items is d.sum()
} -> {
  select: returned_items, delivered_items, return_share_of_delivered is round(returned_items / delivered_items, 6)
}
